cmd:
env | grep -i proxy; python3 - <<'EOF'
import urllib.request
for host in ["https://pypi.org", "https://api.github.com", "https://github.com", "https://raw.githubusercontent.com", "https://www.google.com"]:
    try:
        r = urllib.request.urlopen(host, timeout=10)
        print(host, r.status)
    except Exception as e:
        print(host, "ERR", e)
EOF
